const inkEditor = createInkEditor({$, icon, esc, id, request, transaction, toast, failure,
  onClose:()=>{page='projects';inChat=true;render(true);},
  onSave:async(doc,blob)=>{
    const p=projects.find(p=>p.id===doc.projectId); if(!p) throw new Error('项目已不存在');
    const existing=messages.find(m=>m.id===doc.id);
    const now=Date.now();
    const m={id:doc.id, projectId:p.id, type:'handwriting', name:doc.title||'手写笔记', pageCount:doc.pages.length, created:existing?.created||now, ...(existing?{edited:now}:{})};
    await transaction(['messages','media','ink','projects'],tx=>{
      tx.objectStore('messages').put(m);tx.objectStore('media').put({id:m.id,blob});
      tx.objectStore('ink').put({...doc,draft:false,sourceId:null,updated:now});
      tx.objectStore('ink').delete(doc.draftId);
      tx.objectStore('projects').put({...p,updated:now});
    });
    revokeMedia(m.id);await refresh();page='projects';inChat=true;render(true);toast(existing?'手写笔记已更新':'手写笔记已保存');
  }
});
const noteEditor=createNoteEditor({$,esc,id,request,transaction,toast,failure,openSystemAlarm,
 onDraft:async data=>{const shared={...structuredClone(draft(data.projectId)),text:data.text,taskText:'',taskMode:data.kind==='task'};await transaction(['drafts'],tx=>{tx.objectStore('drafts').put(data);tx.objectStore('drafts').put(shared);});drafts.set(data.projectId,shared);taskMode=shared.taskMode;$('#message-input')?.remove();},
 onClose:()=>{if(editorReturn){page=editorReturn.page;inChat=editorReturn.inChat;activeId=editorReturn.activeId;}render();},
 onSave:async(kind,pid,source,data)=>{
  const p=projects.find(p=>p.id===pid);if(!p)throw new Error('项目已不存在');const now=Date.now();
  await pendingDraftWrites;const cleared=(kind==='task'||data.composer)&&!source?{...structuredClone(draft(pid)),text:'',taskText:'',taskMode:false}:null;
  await transaction([kind==='task'?'tasks':'messages','projects','drafts'],tx=>{
   const value=kind==='task'?{id:source?.id||id(),projectId:pid,text:data.text,done:source?.done||false,created:source?.created||now,dueDate:data.dueDate,reminderTime:data.reminderTime||null,reminderDate:data.reminderDate||null,reminderEnabled:!!data.reminderEnabled,images:data.images}:{...source,id:source?.id||id(),projectId:pid,type:'richtext',text:data.text,html:data.html,created:source?.created||now,edited:source?now:undefined};
   const values=data.composer&&kind==='task'?data.text.split('\n').map(s=>s.trim().replace(/^□\s*/, '').trim()).filter(Boolean).map((text,i)=>({...value,id:id(),text,created:now+i,images:i?[]:value.images})): [value];if(data.composer&&kind==='task'&&!values.length&&data.images.length)values.push(value);values.forEach(v=>tx.objectStore(kind==='task'?'tasks':'messages').put(v));tx.objectStore('projects').put({...p,updated:now});tx.objectStore('drafts').delete(data.id);if(cleared)tx.objectStore('drafts').put(cleared);
  });
  if(kind==='task')orderSnapshot=null;if(cleared){drafts.set(pid,cleared);taskMode=false;$('#message-input')?.remove();}await refresh().catch(failure);await collectUnusedMedia().catch(failure);toast(kind==='task'?'待办已保存':'笔记已保存');
 }
});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2800);}
function failure(e){console.error(e);toast(e?.name==='QuotaExceededError'?'设备空间不足，请先备份并清理空间':e?.message||'保存失败，请重试');}
function request(store,method,...args){return new Promise((resolve,reject)=>{const tx=db.transaction(store,['get','getAll'].includes(method)?'readonly':'readwrite');const req=tx.objectStore(store)[method](...args);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error||req.error);tx.onabort=()=>reject(tx.error||new Error('数据操作未完成'));});}
function transaction(stores,mutate){return new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');try{mutate(tx);}catch(e){tx.abort();reject(e);return;}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('数据操作未完成'));});}
async function refresh(){[projects,messages,tasks,templates]=await Promise.all(['projects','messages','tasks','templates'].map(s=>request(s,'getAll')));if(!projects.some(p=>p.id===activeId))activeId=sortedProjects()[0]?.id;syncReminders();}
function sortedProjects(){return [...projects].sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updated-a.updated);}
function projectMessages(pid=activeId){return messages.filter(m=>m.projectId===pid).sort((a,b)=>a.created-b.created||a.id.localeCompare(b.id));}
function projectStream(pid=activeId){return [...projectMessages(pid),...projectTasks(pid).map(t=>({...t,type:'task'}))].sort((a,b)=>a.created-b.created||(a.origin?.batch===b.origin?.batch?(a.origin?.order??0)-(b.origin?.order??0):0)||a.id.localeCompare(b.id));}
function projectTasks(pid=activeId){return tasks.filter(t=>t.projectId===pid).sort((a,b)=>a.created-b.created||a.id.localeCompare(b.id));}
function project(){return projects.find(p=>p.id===activeId);}
function draft(pid=activeId){let d=drafts.get(pid);if(!d)d={id:pid,text:'',taskText:'',taskMode:false};if(!d.unified){d.text=[d.text||'',d.taskText&&d.taskText!==d.text?d.taskText:''].filter(Boolean).join('\n');d.taskText='';d.unified=true;}drafts.set(pid,d);return d;}
function persistDraft(pid=activeId){const d=structuredClone(draft(pid));pendingDraftWrites=pendingDraftWrites.catch(()=>{}).then(()=>request('drafts','put',d));pendingDraftWrites.catch(failure);}
function rememberDraft(){const input=$('#message-input');if(input&&activeId){draft().text=input.value;draft().taskMode=taskMode;persistDraft();}}
function clearComposerDraft(pid){draft(pid).text='';draft(pid).taskText='';persistDraft(pid);}
function shortTime(ts){const d=new Date(ts);return d.toDateString()===new Date().toDateString()?clockTime(ts):`${d.getMonth()+1}/${d.getDate()}`;}
function clockTime(ts){return new Date(ts).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});}
function dayTime(ts){const d=new Date(ts);return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`;}
function preview(m){if(!m)return '还没有记录，发一条消息开始吧';return m.type==='image'?'[图片]':m.type==='video'?'[视频]':m.type==='handwriting'?'[手写] '+m.name:m.type==='task'?'[待办] '+m.text:m.text;}
function projectIcon(emoji){return icon(({'🌱':'leaf','💼':'case','💡':'bulb','🏠':'house','📚':'book','🎯':'target','🎨':'art','🧭':'compass','🛠️':'tools','🎮':'game','✈️':'plane','📝':'note'})[emoji]||'note');}
function avatar(p){const count=tasks.filter(t=>t.projectId===p.id&&!t.done).length;return `<div class="avatar">${projectIcon(p.emoji)}${count?`<span class="pending-badge" aria-label="${count} 项未完成">${count>99?'99+':count}</span>`:''}</div>`;}
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'rail'}" aria-label="主导航">${mobile?'':'<img class="brand-icon" src="icon.svg" alt="自言">'}${[['projects','chat','项目'],['tasks','tasks','待办'],['settings','settings','设置']].map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function sidebar(){return `<aside class="sidebar"><div class="side-top"><div class="title-row"><h1>自言<span class="brand-sub"> / 项目</span></h1><button class="icon-btn add" data-action="create" aria-label="新建项目">${icon('plus')}</button></div><label class="search">${icon('search')}<input id="project-search" placeholder="搜索项目、笔记与待办" aria-label="搜索项目与笔记" value="${esc(search)}"></label>${searchFilterControls()}<div class="list-caption"><span id="search-caption">${searchActive()?'搜索结果':'我的项目'}</span><span id="search-total">${searchActive()?'':projects.length}</span></div></div><div class="project-list" id="project-list">${projectList()}</div><div class="side-bottom">${icon('lock')} 数据保存在本机</div></aside>`;}
function projectList(){if(searchActive())return globalSearchResults();const q=search.trim().toLowerCase();const matched=sortedProjects().filter(p=>p.name.toLowerCase().includes(q)||[...messages,...tasks].some(m=>m.projectId===p.id&&(m.text||m.name||'').toLowerCase().includes(q)));return matched.map(p=>{const latest=[...projectMessages(p.id),...projectTasks(p.id).map(t=>({...t,type:'task'}))].sort((a,b)=>b.created-a.created)[0];return `<button class="project ${p.pinned?'pinned':''} ${p.id===activeId?'selected':''}" data-project="${p.id}">${avatar(p)}<div class="project-copy"><div class="project-line"><span class="project-name">${p.pinned?'<span class="pin">◆</span>':''}${esc(p.name)}</span><time>${shortTime(p.updated)}</time></div><div class="preview">${esc(preview(latest))}</div></div></button>`;}).join('')||'<div class="empty">没有找到相关记录</div>';}
function header(p){return `<header class="chat-head"><button class="icon-btn mobile-back" data-action="back" aria-label="返回项目列表">${icon('back')}</button>${avatar(p)}<div><h2>${esc(p.name)}</h2><div class="subtitle">${projectMessages().length} 条笔记</div></div><div class="head-right"><span class="local-pill"><span class="dot"></span>仅本机</span><button class="icon-btn" data-action="details" aria-label="项目详情">${icon('more')}</button></div></header>`;}
function taskbar(){const p=project(),list=projectTasks().filter(t=>!t.done);if(!p)return '';return `<section class="taskbar ${p.tasksOpen?'expanded':''}" aria-label="项目待办栏"><button class="taskbar-toggle" data-action="taskbar" aria-expanded="${!!p.tasksOpen}">${icon('tasks')}<span class="taskbar-count">待办 · 未完成 ${list.filter(t=>!t.done).length} 项</span><span class="taskbar-chevron">⌄</span></button><div class="taskbar-drawer"><div class="taskbar-inner"><div class="taskbar-list">${list.map(t=>taskRow(t,true)).join('')||'<div class="taskbar-empty">暂无未完成待办。点击输入框旁的「待办」添加。</div>'}</div><button class="taskbar-close" data-action="taskbar">⌃ 收起待办</button></div></div></section>`;}
function linkCards(text){return [...new Set((text.match(/https?:\/\/[^\s<>"']+/gi)||[]).map(x=>x.replace(/[。，、；！？）)\],.!?;]+$/g,'')))].slice(0,30).map(raw=>{try{const u=new URL(raw);if(!['http:','https:'].includes(u.protocol)||!u.hostname)return '';return `<button class="link-card" data-external="${esc(u.href)}" aria-label="在浏览器打开 ${esc(u.hostname)}"><span class="link-symbol">↗</span><span class="link-copy"><strong>${esc(u.hostname)}</strong><span>${esc(u.pathname==='/'?'网页链接':decodeURI(u.pathname))}</span></span></button>`;}catch{return '';}}).join('');}
function openExternal(url){const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))return;window.ziyanPersistNow();if(window.ZiyanAndroid?.openExternalLink)window.ZiyanAndroid.openExternalLink(parsed.href);else window.open(parsed.href,'_blank','noopener,noreferrer');}
window.ziyanExternalResult=opened=>{if(!opened)toast('没有可用浏览器，请安装或启用浏览器后重试');};
function taskBubble(t){return `<article class="message task-message" data-message="${t.id}"><div class="message-body"><div class="bubble task-bubble">${taskRow(t,'stream')}</div></div><div class="avatar">我</div></article>`;}
function bubble(m){let content;if(['image','video','handwriting'].includes(m.type)){content=`<div class="bubble media-bubble">${m.type==='video'?`<video data-media="${m.id}" controls preload="metadata" playsinline></video>`:`<button class="image-open" ${m.type==='handwriting'?`data-ink="${m.id}"`:`data-image="${m.id}"`} aria-label="${m.type==='handwriting'?'打开手写笔记':'查看大图'}"><img data-media="${m.id}" alt="${esc(m.name)}" loading="lazy"></button>`}<div class="media-name">${esc(m.name)}${m.type==='handwriting'?` · ${m.pageCount} 页 <button class="text-link" data-ink="${m.id}">继续编辑</button>`:''}</div></div>`;}else content=`<div class="bubble ${m.type==='richtext'?'rich-content rich-bubble':''}">${(m.text||'').length>12000?esc(m.text.slice(0,8000))+'…':m.type==='richtext'?cleanRich(m.html):esc((m.text||'').replace(/https?:\/\/[^\s<>"']+/gi,'').trim())}</div>`;return `<article class="message" data-message="${m.id}"><div class="message-body">${m.edited?'<div class="edited-label">已编辑</div>':''}<button class="message-delete" data-menu="${m.id}" aria-label="消息操作">${icon('more')}</button>${m.origin?`<div class="source-meta">${esc(m.origin.sender||'未知发送者')} · ${esc(m.origin.time||'原时间未提供')}</div>`:''}${content}${(m.text||'').length>12000?`<button class="text-link" data-read-message="${m.id}">查看完整长消息（${m.text.length} 字）</button>`:''}${(m.attachments||[]).map(a=>`<div class="bubble media-bubble"><video data-media="${a.id}" controls preload="metadata" playsinline></video><div class="media-name">${esc(a.name)}</div></div>`).join('')}${linkCards(m.text||'')}</div><div class="avatar">${m.origin?'微':'我'}</div></article>`;}
function chat(){const p=project();if(!p)return '<div class="empty">新建一个项目，开始记录。<br><button class="primary" data-action="create">新建项目</button></div>';const all=projectStream(),limit=limits.get(activeId)||60;let prev;const content=all.slice(-limit).map(m=>{const newDay=!prev||dayTime(prev.created)!==dayTime(m.created);const sep=!prev||newDay||m.created-prev.created>300000?`<div class="date-separator" data-timestamp="${m.created}">${newDay?dayTime(m.created)+' ':''}${clockTime(m.created)}</div>`:'';prev=m;return sep+(m.type==='task'?taskBubble(m):bubble(m));}).join('');const text=draft().text;return `${header(p)}${taskbar()}<section class="messages" id="messages" aria-label="项目笔记">${all.length>limit?'<button class="load-older" data-action="older">加载更早的记录</button>':''}${content||'<div class="empty chat-empty">把想法，留在这里。<br><span>右滑回首页 · 左滑写手写笔记</span></div>'}</section><div class="compose-wrap"><form class="composer ${taskMode?'task-composer':''}" id="compose"><div class="compose-heading"><span>${taskMode?'待办 · 回车添加下一项':'笔记'}</span><button type="button" data-action="expand-composer" aria-label="全屏展开输入区">展开</button></div><textarea id="message-input" placeholder="${taskMode?'输入待办，回车继续下一项…':'写点什么，发给自己…'}" aria-label="${taskMode?'待办内容':'笔记内容'}" maxlength="2000000" rows="2">${esc(text)}</textarea>${taskMode?'<div class="task-compose-options"><div id="task-input-preview">'+taskInputPreview(text)+'</div><button type="button" class="text-link" data-action="task-details">图片 / 截止 / 提醒</button></div>':''}<div class="composer-row"><div class="composer-tools"><button type="button" class="tool ${taskMode?'on':''}" data-action="task-mode" aria-pressed="${taskMode}">${icon('tasks')}<span>切换</span></button><span class="input-hint">${taskMode?'发送到消息流与待办栏':'草稿自动保存'}</span></div><div class="send-tools"><button type="button" class="icon-btn attach-toggle" data-action="attachments" aria-label="添加附件">${icon('plus')}</button><button type="submit" class="send" id="send-button" ${composerValid(text)?'':'disabled'}>${taskMode?'保存待办':'发送'}</button></div></div></form>${attachmentOpen?`<div class="attachment-panel"><button data-pick="album">${icon('image')}<span>相册</span></button><button data-pick="camera">${icon('camera')}<span>拍照</span></button><button data-pick="video">${icon('video')}<span>视频</span></button><button data-action="handwrite">${icon('art')}<span>手写</span></button><button data-action="rich-note">${icon('note')}<span>图文笔记</span></button><button data-action="templates">${icon('note')}<span>模板</span></button></div>`:''}<div class="composer-note">${icon('lock')} 本地保存 · 长按消息可编辑或整理</div></div>`;}
function composerValid(text){return taskMode?text.split('\n').some(s=>s.trim().replace(/^□\s*/, '').trim()):!!text.trim();}
function taskInputPreview(text){const lines=text.split('\n').map(s=>s.trim()).filter(Boolean);return lines.length?`<span class="task-entry-count">将保存 ${lines.length} 项</span>`:'';}
function garden(scoped){const total=scoped.length,done=scoped.filter(t=>t.done).length,ratio=total?done/total:0;const count=Math.ceil(ratio*24);return `<div class="task-summary garden-card"><div><strong>${done} / ${total}</strong><span>项已完成 · ${total?Math.round(ratio*100)+'%':'暂无待办'}</span></div><div class="garden" role="img" aria-label="完成比例 ${Math.round(ratio*100)}%，${count} 株植物">${Array.from({length:count},(_,i)=>`<span style="left:${3+(i*29)%92}%;bottom:${4+(i*7)%20}px;font-size:${20+(i%3)*8}px">${i%5===0?'🌳':i%3===0?'🌼':'🌱'}</span>`).join('')}</div></div>`;}
function locateBadge(){if(searchActive()){search='';Object.keys(searchFilters).forEach(k=>searchFilters[k]='');render();}const list=sortedProjects().filter(p=>tasks.some(t=>t.projectId===p.id&&!t.done));if(!list.length)return toast('没有带待办角标的项目');const p=list[(list.findIndex(p=>p.id===badgeCursor)+1)%list.length];badgeCursor=p.id;const row=$(`[data-project="${p.id}"]`);row?.scrollIntoView({block:'center',behavior:'smooth'});row?.classList.add('highlight');setTimeout(()=>row?.classList.remove('highlight'),2400);}
function tasksPage(){if(taskProject&&!projects.some(p=>p.id===taskProject))taskProject='';const scoped=tasks.filter(t=>!taskProject||t.projectId===taskProject);let filtered=scoped.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));if(!orderSnapshot)orderSnapshot=[...filtered].sort(taskCompare).map(t=>t.id);const order=new Map(orderSnapshot.map((id,i)=>[id,i]));filtered.sort((a,b)=>(order.get(a.id)??1e9)-(order.get(b.id)??1e9)||taskCompare(a,b));return `<section class="page"><h2>待办事项</h2><p class="lead">截止三天内及逾期事项标红，按紧急程度排序。</p>${garden(scoped)}<label class="task-project-filter">项目<button data-action="task-project-picker" class="secondary">${esc(projects.find(p=>p.id===taskProject)?.name||'全部项目')} ⌄</button><select hidden id="task-project-filter"><option value="">全部项目</option>${sortedProjects().map(p=>`<option value="${p.id}" ${p.id===taskProject?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="filters">${[['open','未完成'],['done','已完成'],['all','全部']].map(([v,t])=>`<button data-filter="${v}" class="${taskFilter===v?'active':''}">${t}</button>`).join('')}</div>${filtered.map(t=>taskRow(t,false)).join('')||'<div class="empty">这里还没有待办。</div>'}</section>`;}
function reminderSettings(){let status={notifications:false,exact:false,channel:false,scheduled:0,error:false};try{if(window.ZiyanAndroid?.reminderStatus)status=JSON.parse(window.ZiyanAndroid.reminderStatus());}catch{}return `<div class="setting-card" id="reminder-settings"><h3>提醒授权与状态</h3>${window.ZiyanAndroid?`<p>通知：${status.notifications?'已允许':'未允许'} · 提醒渠道：${status.channel?'已开启':'未开启'}<br>精确闹钟：${status.exact?'已允许':'未允许'}<br>已预约 ${status.scheduled} 项未来提醒${status.error?' · 预约失败，请重试':''}</p><div class="settings-actions"><button class="primary" data-action="reminder-authorize">开启提醒权限</button><button class="secondary" data-action="notification-settings">通知与声音设置</button><button class="secondary" data-action="reminder-refresh">刷新状态</button></div>`:'<p>应用内提醒需要安卓 APK；网页版只保存偏好。</p>'}<p class="fine-print">授权不等于设置提醒。为待办选择未来日期、时间并启用后才预约；通知声音受静音、勿扰及渠道设置影响。</p></div>`;}
function taskProjectPicker(){showDialog(`<h3>筛选项目</h3><input id="task-project-query" type="search" placeholder="搜索项目" aria-label="搜索待办项目"><div id="task-project-options"></div><div class="dialog-actions"><button class="secondary" data-close>取消</button></div>`);function draw(){const q=$('#task-project-query').value.trim().toLowerCase();$('#task-project-options').innerHTML=`<button class="picker-option" data-id="">全部项目</button>`+sortedProjects().filter(p=>p.name.toLowerCase().includes(q)).map(p=>`<button class="picker-option" data-id="${p.id}">${esc(p.name)}${p.id===taskProject?' ✓':''}</button>`).join('');$('#task-project-options').querySelectorAll('button').forEach(b=>b.onclick=()=>{taskProject=b.dataset.id;orderSnapshot=null;closeDialog();render();});}$('#task-project-query').oninput=draw;draw();$('#task-project-query').focus();}
let gardenMotion=false,motionFrame=0,motionTarget=0,motionAngle=0,motionVelocity=0;
function gardenTick(){const garden=$('.garden');if(!garden){motionFrame=0;motionAngle=motionVelocity=motionTarget=0;return;}motionVelocity=(motionVelocity+(motionTarget-motionAngle)*.065)*.85;motionAngle+=motionVelocity;motionTarget*=.92;garden.style.setProperty('--sway',Math.max(-22,Math.min(22,motionAngle))+'deg');if(Math.abs(motionVelocity)+Math.abs(motionAngle)+Math.abs(motionTarget)>.02)motionFrame=requestAnimationFrame(gardenTick);else{garden.style.setProperty('--sway','0deg');motionFrame=0;}}
window.ziyanGardenMotion=(x,y)=>{if(!gardenMotion||document.hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;motionTarget=Math.max(-22,Math.min(22,-Number(x)*4+Number(y)*.5));if(!motionFrame)motionFrame=requestAnimationFrame(gardenTick);};
function updateGardenMotion(){gardenMotion=page==='tasks'&&!document.hidden;window.ZiyanAndroid?.setGardenMotion?.(gardenMotion);if(!gardenMotion){cancelAnimationFrame(motionFrame);motionFrame=0;motionAngle=motionVelocity=motionTarget=0;} }
document.addEventListener('visibilitychange',updateGardenMotion);
window.addEventListener('devicemotion',e=>{if(!window.ZiyanAndroid)window.ziyanGardenMotion(e.accelerationIncludingGravity?.x||0,e.acceleration?.y||0);});
function settingsPage(){const native=!!window.ZiyanAndroid;return `<section class="page settings-page"><h2>我的空间</h2><p class="lead">不用登录，内容只保存在本机。</p><div class="setting-card identity-card"><img src="icon.svg" width="57" height="57" alt=""><div><h3>自言 <span class="count">${native?'APK '+esc(window.ZiyanAndroid.version()):'v0.11.0'}</span></h3><p>${projects.length} 个项目 · ${messages.length} 条笔记 · ${tasks.length} 项待办</p></div></div>${reminderSettings()}<div class="setting-card"><h3>完整备份与恢复</h3><p>包含全部项目、笔记、图片、视频、待办、手写原始笔迹、模板和草稿。可在另一浏览器或 APK 中导入，继续查看和编辑。</p><div class="settings-actions"><button class="primary" data-action="export">${icon('download')} 导出完整备份</button><button class="secondary" data-action="import">${icon('upload')} 导入备份</button></div><p class="fine-print">${native?'导出时选择系统文件保存位置。旧网页版 JSON 备份可以直接导入。':'HTML 是应用，JSON 备份是你的内容，请一起保留。'}导入会在确认后替换当前数据。</p></div><div class="setting-card"><h3>笔记模板</h3><p>题目与解答、公式推导、错题记录、实验记录，支持修改与自建。</p><button class="secondary" data-action="templates">管理模板</button></div><div class="setting-card"><h3>${native?'应用存储':'设备存储'}</h3><p id="storage-info">正在读取…</p>${native?'':'<button class="secondary" data-action="persist">申请保留本地数据</button>'}<p>${native?'内容保存在应用独立空间，清理浏览器不会影响这里的记录。卸载或清除本应用数据会删除记录，请定期导出备份。':'清理浏览器数据或卸载可能删除记录，请定期导出备份。'}</p></div><div class="setting-card"><h3>${native?'完全离线':'安卓使用'}</h3><p>${native?'界面内置在 APK 中，无需网络或本地服务器。不申请联网权限、不加载远程网页、不包含广告或统计服务。相册、拍照和文件保存通过系统界面操作。':'单文件 HTML 可离线打开；完整 PWA 通过 localhost 或 HTTPS 首次加载后，可添加到桌面。不同浏览器、不同地址的数据独立，迁移请使用备份。'}</p>${native?'':'<button class="secondary" data-action="install">安装说明</button>'}</div></section>`;}
let chatViewport;
function captureChat(list){
 if(!list)return null;const box=list.getBoundingClientRect(),point=box.top+Math.min(32,box.height/3),el=[...list.querySelectorAll('[data-message]')].find(el=>el.getBoundingClientRect().bottom>point);
 return {bottom:list.scrollHeight-list.scrollTop-list.clientHeight<48,top:list.scrollTop,id:el?.dataset.message,inset:el?point-el.getBoundingClientRect().top:0,point};
}
function watchChat(list,initial){
 chatViewport?.disconnect();let anchor=initial||captureChat(list),adjusting=false,frame,animation,drawerAnimating=false;
 function restore(){if(!list.isConnected||!anchor)return;adjusting=true;const box=list.getBoundingClientRect();if(anchor.bottom)list.scrollTop=list.scrollHeight;else{const el=anchor.id?list.querySelector(`[data-message="${anchor.id}"]`):null;const point=drawerAnimating?anchor.point:Math.max(box.top+8,Math.min(anchor.point,box.bottom-8));if(el)list.scrollTop+=el.getBoundingClientRect().top+anchor.inset-point;else list.scrollTop=anchor.top;}cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{adjusting=false;});}
 function remember(){anchor=captureChat(list);}
 // The drawer covers the top of the chat. Keep text at its screen position,
 // even when the old reading point is temporarily clipped by the opening drawer.
 function animate(){cancelAnimationFrame(animation);drawerAnimating=true;const until=performance.now()+280;const tick=()=>{restore();if(performance.now()<until)animation=requestAnimationFrame(tick);else{drawerAnimating=false;remember();}};animation=requestAnimationFrame(tick);}
 const observer=new ResizeObserver(restore);observer.observe(list);list.querySelectorAll('[data-message]').forEach(el=>observer.observe(el));
 list.addEventListener('scroll',()=>{if(!adjusting)remember();},{passive:true});
 for(const event of ['pointerdown','wheel','touchstart'])list.addEventListener(event,()=>{cancelAnimationFrame(animation);drawerAnimating=false;adjusting=false;remember();},{passive:true});
 chatViewport={capture:()=>anchor,restore,remember,animate,disconnect:()=>{observer.disconnect();cancelAnimationFrame(frame);cancelAnimationFrame(animation);}};restore();
}
function render(bottom=false){rememberDraft();renderVersion++;const route=`${page}/${inChat}/${activeId}`;const same=app.dataset.route===route;const oldPage=same?$('.page')?.scrollTop:0,oldMessages=same?captureChat($('#messages')):null,oldTasks=same?$('.taskbar-list')?.scrollTop:0;chatViewport?.disconnect();app.className=page!=='projects'?'other-page':inChat?'in-chat':'';app.dataset.route=route;app.innerHTML=`${nav()}${sidebar()}<main class="main">${page==='projects'?chat():page==='tasks'?tasksPage():settingsPage()}</main>${page==='projects'&&inChat?'':nav(true)}`;if($('.page'))$('.page').scrollTop=oldPage||0;if($('.taskbar-list'))$('.taskbar-list').scrollTop=oldTasks||0;if(page==='projects'){const list=$('#messages');if(list){list.style.scrollBehavior='auto';list.scrollTop=bottom||!oldMessages?list.scrollHeight:oldMessages.top;watchChat(list,bottom||!oldMessages?{bottom:true}:oldMessages);}loadMedia(renderVersion).catch(failure);}else loadMedia(renderVersion).catch(failure);if(page==='settings')storageInfo().catch(failure);updateGardenMotion();}
async function loadMedia(version){await Promise.all([...document.querySelectorAll('#app [data-media]')].map(async el=>{const mid=el.dataset.media;if(!mediaUrls.has(mid)){const record=await request('media','get',mid);if(!record){el.replaceWith(document.createTextNode('附件无法读取'));return;}mediaUrls.set(mid,URL.createObjectURL(record.blob));}if(version!==renderVersion)return;el.addEventListener('load',()=>{chatViewport?.restore();},{once:true});el.src=mediaUrls.get(mid);}));}
function openProject(pid,mid){rememberDraft();$('#message-input')?.remove();activeId=pid;page='projects';inChat=true;taskMode=!!draft().taskMode;attachmentOpen=false;if(mid){const all=projectStream(),at=all.findIndex(m=>m.id===mid);if(at>=0)limits.set(pid,Math.max(limits.get(pid)||60,all.length-at+5));}render(!mid);if(mid){const el=$(`[data-message="${mid}"]`);el?.scrollIntoView({block:'center'});el?.classList.add('highlight');}}
function showDialog(html){if(dialog.open)dialog.close();dialog.className='';dialog.onclick=null;dialog.oncancel=null;dialog.innerHTML=html;dialog.showModal();dialog.scrollTop=0;}
function closeDialog(){if(dialog.dataset.sending==='1')return;dialog.close();dialog.onclick=null;dialog.oncancel=null;}
function searchActive(){return !!search.trim()||Object.values(searchFilters).some(Boolean);}
function typeOptions(value){return [['','全部类型'],['text','文字'],['richtext','图文'],['image','图片'],['video','视频'],['handwriting','手写'],['task','待办']].map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('');}
function searchFilterControls(){return `<details class="search-filters" ${Object.values(searchFilters).some(Boolean)?'open':''}><summary>筛选项目、类型与日期</summary><div class="search-filter-grid"><label>项目<select data-search-filter="project" aria-label="搜索项目筛选"><option value="">全部项目</option>${sortedProjects().map(p=>`<option value="${p.id}" ${p.id===searchFilters.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>内容类型<select data-search-filter="type" aria-label="搜索类型筛选">${typeOptions(searchFilters.type)}</select></label><label>开始日期<input type="date" data-search-filter="from" aria-label="搜索开始日期" value="${esc(searchFilters.from)}"></label><label>结束日期<input type="date" data-search-filter="to" aria-label="搜索结束日期" value="${esc(searchFilters.to)}"></label></div><button class="text-link" data-action="clear-search">清除搜索和筛选</button></details>`;}
function filterSearch(q,filters){const term=q.trim().toLowerCase();return [...messages,...tasks.map(t=>({...t,type:'task'}))].filter(m=>(!filters.project||m.projectId===filters.project)&&(!filters.type||m.type===filters.type)&&(!filters.from||m.created>=new Date(filters.from+'T00:00:00').getTime())&&(!filters.to||m.created<=dueEnd(filters.to))&&(!term||[m.text,m.name,m.origin?.sender,m.origin?.time].filter(Boolean).join(' ').toLowerCase().includes(term))).sort((a,b)=>b.created-a.created||a.id.localeCompare(b.id));}
function searchSnippet(m,q){const text=m.text||m.name||preview(m),term=q.trim(),at=term?text.toLowerCase().indexOf(term.toLowerCase()):-1,start=Math.max(0,at-30),end=Math.min(text.length,Math.max(start+140,at+term.length)),snippet=text.slice(start,end),offset=at-start;const content=at<0?esc(snippet):esc(snippet.slice(0,offset))+'<mark>'+esc(snippet.slice(offset,offset+term.length))+'</mark>'+esc(snippet.slice(offset+term.length));return (start?'…':'')+content+(end<text.length?'…':'');}
function searchResult(m,q){const kind=({text:'文字',richtext:'图文',image:'图片',video:'视频',handwriting:'手写',task:m.done?'已完成待办':'未完成待办'})[m.type];return `<button class="search-result" ${m.type==='task'?`data-search-task="${m.id}"`:`data-search-message="${m.id}" data-search-project="${m.projectId}"`}><span class="result-project">${esc(projects.find(p=>p.id===m.projectId)?.name)} · ${kind}${m.origin?' · '+esc(m.origin.sender||'未知发送者')+' · '+esc(m.origin.time||'原时间未提供'):''}</span><span class="result-snippet">${searchSnippet(m,q)}</span><span class="result-time">${dayTime(m.created)} ${clockTime(m.created)}</span></button>`;}
function globalSearchResults(){if(searchFilters.from&&searchFilters.to&&searchFilters.from>searchFilters.to)return '<div class="empty">开始日期不能晚于结束日期</div>';const found=filterSearch(search,searchFilters);const named=search.trim()&&!Object.values(searchFilters).some(Boolean)?sortedProjects().filter(p=>p.name.toLowerCase().includes(search.trim().toLowerCase())).map(p=>`<button class="search-result" data-project="${p.id}"><span class="result-project">项目</span>${esc(p.name)}</button>`).join(''):'';return named+found.map(m=>searchResult(m,search)).join('')||'<div class="empty">没有找到相关记录</div>';}
function updateGlobalSearch(){const list=$('#project-list');if(list)list.innerHTML=projectList();const caption=$('#search-caption');if(caption)caption.textContent=searchActive()?'搜索结果':'我的项目';const total=$('#search-total');if(total)total.textContent=searchActive()?'':projects.length;}
document.addEventListener('change',e=>{const key=e.target.dataset.searchFilter;if(key&&Object.hasOwn(searchFilters,key)){searchFilters[key]=e.target.value;updateGlobalSearch();}});
async function openTaskResult(tid){const t=tasks.find(t=>t.id===tid);if(!t)return;closeDialog();if(t.done){taskFilter='all';navigatePage('tasks');}else{const p=projects.find(p=>p.id===t.projectId);if(!p)return;await request('projects','put',{...p,tasksOpen:true});await refresh();openProject(p.id);}const row=$(`[data-task-row="${tid}"]`);row?.scrollIntoView({block:'center'});row?.classList.add('highlight');}
function forwardDialog(mid,isTask=false){
 const source=(isTask?tasks:messages).find(m=>m.id===mid);if(!source)return;
 const targets=sortedProjects().filter(p=>p.id!==source.projectId),selected=new Set();let sending=false;
 showDialog(`<header class="editor-head"><button class="icon-btn" data-close aria-label="返回聊天">${icon('back')}</button><h2>选择目标项目</h2><button class="send" id="forward-confirm" disabled>转发</button></header><div class="forward-search"><label class="search">${icon('search')}<input id="forward-search" placeholder="搜索项目" aria-label="搜索目标项目"></label><p>${isTask?'新副本为未完成待办，保留截止日期；提醒不启用。原待办保留。':'可多选 · 原笔记保留'}</p></div><div class="forward-scroll"><section id="forward-recent" hidden><h3>最近转发</h3><div class="forward-recents"></div></section><h3>全部项目</h3><div class="forward-targets"></div><p id="forward-empty" class="dialog-copy" hidden>没有匹配的项目</p></div><footer class="forward-footer" role="status">请选择接收项目</footer>`);
 dialog.className='forward-page';
 const row=p=>`<button data-forward-project="${p.id}" aria-pressed="${selected.has(p.id)}"><span class="avatar">${projectIcon(p.emoji)}</span><span class="forward-name">${esc(p.name)}</span><span class="forward-check">${selected.has(p.id)?icon('check'):''}</span></button>`;
 let recent=[];
 function paint(){const q=$('#forward-search').value.trim().toLowerCase(),found=targets.filter(p=>p.name.toLowerCase().includes(q));$('.forward-targets').innerHTML=found.map(row).join('');$('#forward-empty').hidden=!!found.length;const shown=recent.map(pid=>targets.find(p=>p.id===pid)).filter(p=>p&&p.name.toLowerCase().includes(q));$('#forward-recent').hidden=!shown.length;$('.forward-recents').innerHTML=shown.map(row).join('');$('#forward-confirm').disabled=sending||!selected.size;$('#forward-confirm').textContent=sending?'正在转发…':selected.size?`转发 (${selected.size})`:'转发';$('.forward-footer').textContent=selected.size?`已选择 ${selected.size} 个项目`:'请选择接收项目';}
 $('#forward-search').oninput=paint;
 dialog.onclick=async e=>{const target=e.target.closest('[data-forward-project]');if(target&&!sending){const pid=target.dataset.forwardProject;selected.has(pid)?selected.delete(pid):selected.add(pid);paint();}if(!e.target.closest('#forward-confirm')||sending||!selected.size)return;sending=true;dialog.dataset.sending='1';paint();dialog.querySelectorAll('button,input').forEach(el=>el.disabled=true);try{await forwardMessage(mid,[...selected],isTask);dialog.dataset.sending='0';closeDialog();}catch(error){failure(error);sending=false;dialog.dataset.sending='0';dialog.querySelectorAll('button,input').forEach(el=>el.disabled=false);paint();}};
 dialog.oncancel=e=>{if(sending)e.preventDefault();};
 paint();request('meta','get','forward-recent').then(value=>{if(dialog.open&&dialog.classList.contains('forward-page')){recent=value?.projects||[];paint();}}).catch(failure);
}
async function forwardMessage(mid,pids,isTask=false){
 if(busy)throw new Error('正在保存，请稍后再试');
 const original=(isTask?tasks:messages).find(m=>m.id===mid),targets=[...new Set(pids)].map(pid=>projects.find(p=>p.id===pid));
 if(!original||!targets.length||targets.some(p=>!p||p.id===original.projectId))throw new Error('原记录或目标项目已不存在');
 busy=true;
 try{
  const now=Date.now(),refs=isTask?[...(original.images||[])]:original.type==='richtext'?richMedia(original.html):['image','video','handwriting'].includes(original.type)?[mid]:[];refs.push(...(original.attachments||[]).map(a=>a.id));
  const attachments=await Promise.all(refs.map(async ref=>{const data=await request('media','get',ref);if(!data?.blob)throw new Error('附件缺失，未转发');return [ref,data.blob];}));
  const saved=original.type==='handwriting'?await request('ink','get',mid):null;
  if(original.type==='handwriting'&&(!saved||saved.draft))throw new Error('原始笔迹缺失，未转发');
  const copies=targets.map(target=>{const copy={...structuredClone(original),id:id(),projectId:target.id,created:now};delete copy.edited;if(isTask){copy.done=false;copy.reminderEnabled=false;}const remap=new Map(),media=attachments.map(([ref,blob])=>{const next=ref===mid?copy.id:id();remap.set(ref,next);return {id:next,blob};});
   if(original.type==='richtext'){const template=document.createElement('template');template.innerHTML=cleanRich(original.html);template.content.querySelectorAll('img[data-media]').forEach(img=>img.dataset.media=remap.get(img.dataset.media));copy.html=cleanRich(template.innerHTML);}
   if(isTask)copy.images=(original.images||[]).map(mid=>remap.get(mid));if(original.attachments)copy.attachments=original.attachments.map(a=>({...a,id:remap.get(a.id)}));
   const ink=saved?{...structuredClone(saved),id:copy.id,projectId:target.id,draft:false,sourceId:null,updated:now}:null;if(ink)delete ink.draftId;return {target,copy,media,ink};});
  await transaction([isTask?'tasks':'messages','media','ink','projects','meta'],tx=>{for(const {target,copy,media,ink} of copies){tx.objectStore(isTask?'tasks':'messages').add(copy);media.forEach(m=>tx.objectStore('media').add(m));if(ink)tx.objectStore('ink').add(ink);tx.objectStore('projects').put({...target,updated:now});}const store=tx.objectStore('meta'),r=store.get('forward-recent');r.onsuccess=()=>store.put({id:'forward-recent',projects:[...new Set([...targets.map(p=>p.id),...(r.result?.projects||[])])].slice(0,8)});});
  await refresh().catch(failure);render();toast(targets.length===1?`已转发到「${targets[0].name}」`:`已转发到 ${targets.length} 个项目`);
 }finally{busy=false;}
}
