function details(){const p=project();if(!p)return;showDialog(`<div class="detail-title">${avatar(p)}<h3>${esc(p.name)}</h3></div><div class="menu-list"><button id="edit-project">编辑名称与图标</button><button id="pin-project">${p.pinned?'取消置顶':'置顶项目'}</button><button id="search-project">搜索笔记与待办</button><button id="view-attachments">图片、视频与手写</button><button id="export-project">导出 Markdown</button><button id="delete-project">删除项目</button></div><div class="dialog-actions"><button class="secondary" data-close>关闭</button></div>`);$('#edit-project').onclick=()=>projectEditor(p);$('#pin-project').onclick=async()=>{try{await request('projects','put',{...p,pinned:!p.pinned});await refresh();closeDialog();render();}catch(e){failure(e);}};$('#search-project').onclick=()=>searchProject(false);$('#view-attachments').onclick=()=>searchProject(true);$('#export-project').onclick=()=>exportProject(p).catch(failure);$('#delete-project').onclick=()=>{closeDialog();deleteProject(p);};}
function searchProject(mediaOnly){const p=project();showDialog(`<h3>${mediaOnly?'附件与手写':'搜索本项目'}</h3><label class="search"><input id="inside-search" aria-label="搜索本项目" placeholder="输入关键词（可留空按条件查找）"></label><div class="search-filter-grid"><label>内容类型<select id="inside-type" aria-label="本项目搜索类型">${typeOptions('')}</select></label><label>开始日期<input id="inside-from" aria-label="本项目开始日期" type="date"></label><label>结束日期<input id="inside-to" aria-label="本项目结束日期" type="date"></label></div><div id="inside-results" class="inside-results"></div><div class="dialog-actions"><button class="secondary" data-close>关闭</button></div>`);const update=()=>{const q=$('#inside-search').value,filters={project:p.id,type:$('#inside-type').value,from:$('#inside-from').value,to:$('#inside-to').value};if(filters.from&&filters.to&&filters.from>filters.to){$('#inside-results').innerHTML='<p class="dialog-copy">开始日期不能晚于结束日期</p>';return;}const found=filterSearch(q,filters).filter(m=>!mediaOnly||['image','video','handwriting','richtext'].includes(m.type));$('#inside-results').innerHTML=found.map(m=>searchResult(m,q)).join('')||'<p class="dialog-copy">没有相关记录</p>';};$('#inside-search').oninput=update;for(const key of ['inside-type','inside-from','inside-to'])$('#'+key).onchange=update;update();}
async function sendNote(){
 if(busy||!project())return;rememberDraft();await pendingDraftWrites;const expandedDraft=await request('drafts','get',`edit-compose-${activeId}`);if(expandedDraft){await expandComposer();return noteEditor.save();}const input=$('#message-input'),text=input.value.trim();if(!composerValid(text))return;
 busy=true;const form=$('#compose');form.inert=true;$('#send-button').disabled=true;const p=project(),now=Date.now(),mode=taskMode;
 try{await pendingDraftWrites;const cleared={...structuredClone(draft(p.id)),text:'',taskText:'',taskMode:false};
 await transaction([mode?'tasks':'messages','projects','drafts'],tx=>{if(mode){text.split('\n').map(s=>s.trim().replace(/^□\s*/, '').trim()).filter(Boolean).forEach((s,i)=>tx.objectStore('tasks').add({id:id(),projectId:p.id,text:s,done:false,created:now+i,dueDate:null,images:[]}));}else tx.objectStore('messages').add({id:id(),projectId:p.id,type:'text',text,created:now});tx.objectStore('projects').put({...p,updated:now});tx.objectStore('drafts').put(cleared);tx.objectStore('drafts').delete(`edit-compose-${p.id}`);});
 drafts.set(p.id,cleared);input.remove();taskMode=false;attachmentOpen=false;await refresh().catch(failure);render(!mode);if(!mode)$('#message-input')?.focus();
 }finally{busy=false;form.inert=false;if($('#send-button'))$('#send-button').disabled=!composerValid($('#message-input')?.value||'');}
}
async function toggleTask(tid){const t=tasks.find(t=>t.id===tid);if(!t)return;const updated={...t,done:!t.done};await request('tasks','put',updated);tasks=tasks.map(x=>x.id===tid?updated:x);document.querySelectorAll(`[data-task-row="${tid}"]`).forEach(row=>{if(updated.done&&row.classList.contains('bar-task')){row.remove();return;}row.classList.toggle('done',updated.done);row.classList.toggle('urgent',!updated.done&&isUrgent(updated));const check=$('[data-toggle]',row);check.classList.toggle('checked',updated.done);check.innerHTML=updated.done?icon('check'):'';check.setAttribute('aria-pressed',updated.done);check.setAttribute('aria-label',updated.done?'标为未完成':'完成待办');});if(page==='projects'){render();return;}const summary=$('.task-summary');if(summary)summary.outerHTML=garden(tasks.filter(t=>!taskProject||t.projectId===taskProject));syncReminders();const bar=$('.taskbar-count');if(bar)bar.textContent=`待办 · 未完成 ${projectTasks().filter(t=>!t.done).length} 项`;$('#project-list').innerHTML=projectList();const list=$('.taskbar-list');if(list&&!$('.bar-task',list)&&!$('.taskbar-empty',list))list.innerHTML='<div class="taskbar-empty">暂无未完成待办。</div>';}
function taskMenu(tid,point){const t=tasks.find(t=>t.id===tid);if(!t)return;showMenu([{id:'edit-task',label:'编辑内容 / 图片 / 截止 / 提醒',run:()=>openEditor('task',t)},{id:'forward-task',label:'转发到其他项目',run:()=>forwardDialog(tid,true)},{id:'task-reminder',label:'设置提醒闹钟',run:()=>taskReminder(tid)},{id:'task-select',label:'选择部分文字',run:()=>selectText(t.text)},{id:'task-copy',label:'复制文字',run:()=>copyText(t.text)},{id:'task-delete',label:'删除待办',run:()=>confirmAction('删除待办？',t.text,'删除',async()=>{await request('tasks','delete',tid);await request('drafts','delete',`edit-task-${tid}`);await refresh();render();await collectUnusedMedia();})}],point,$(`[data-task-row="${tid}"]`));}
function messageMenu(mid,point){if(tasks.some(t=>t.id===mid))return taskMenu(mid,point);const m=messages.find(m=>m.id===mid);if(!m)return;const text=['text','richtext'].includes(m.type),items=[];if(text){items.push({id:'copy-message',label:'复制文字',run:()=>copyText(m.text)},{id:'edit-message',label:'编辑笔记',run:()=>openEditor('note',m)},{id:'select-message',label:'选择部分文字',run:()=>selectText(m.text)},{id:'convert-message',label:'转为待办',run:async()=>{if(m.attachments?.length)throw new Error('含视频的原消息请保留为笔记，可另建待办');await transaction(['messages','tasks','drafts'],tx=>{tx.objectStore('messages').delete(m.id);tx.objectStore('tasks').put({id:m.id,projectId:m.projectId,text:m.text,created:m.created,done:false,dueDate:null,images:m.type==='richtext'?richMedia(m.html):[]});tx.objectStore('drafts').delete(`edit-note-${m.id}`);});await refresh();render();toast('已转为待办');}});}else{if(m.type==='handwriting')items.push({id:'edit-handwriting',label:'继续编辑手写',run:()=>openHandwriting(m.id)});items.push({id:'save-media',label:m.type==='handwriting'?'保存预览图片':'保存附件',run:async()=>{const data=await request('media','get',m.id);const saved=await download(data.blob,m.type==='handwriting'?m.name+'.png':m.name);if(window.ZiyanFiles)toast(saved?'附件已保存':'已取消保存');}});}items.push({id:'forward-message',label:'转发到其他项目',run:()=>forwardDialog(m.id)},{id:'delete-message',label:'删除记录',run:()=>confirmAction('删除记录？','删除后无法撤销。','删除',async()=>{const ink=await request('ink','getAll');await transaction(['messages','media','ink','drafts'],tx=>{tx.objectStore('messages').delete(mid);tx.objectStore('media').delete(mid);tx.objectStore('drafts').delete(`edit-note-${mid}`);ink.filter(d=>d.id===mid||d.sourceId===mid).forEach(d=>tx.objectStore('ink').delete(d.id));});revokeMedia(mid);await refresh();render();await collectUnusedMedia();})});showMenu(items,point,$(`[data-message="${mid}"]`));}
function templatesDialog(){showDialog(`<h3>笔记模板</h3><div class="template-list">${templates.map(t=>`<div class="template-row"><button class="template-use" data-template-use="${t.id}">${esc(t.name)}</button><button class="text-link" data-template-edit="${t.id}">编辑</button></div>`).join('')}</div><div class="dialog-actions"><button class="secondary" id="new-template">新增模板</button><button class="secondary" data-close>关闭</button></div>`);dialog.querySelectorAll('[data-template-use]').forEach(b=>b.onclick=()=>{if(!project()||page!=='projects'){toast('请先进入一个项目，再使用模板');return;}rememberDraft();$('#message-input')?.remove();const t=templates.find(t=>t.id===b.dataset.templateUse);const combined=[draft().text,t.text].filter(Boolean).join('\n\n');if(combined.length>2000000){toast('内容超过 200 万字，请先保存当前草稿');render();return;}draft().text=combined;taskMode=false;draft().taskMode=false;persistDraft();closeDialog();attachmentOpen=false;render();$('#message-input')?.focus();});dialog.querySelectorAll('[data-template-edit]').forEach(b=>b.onclick=()=>templateEditor(templates.find(t=>t.id===b.dataset.templateEdit)));$('#new-template').onclick=()=>templateEditor();}
