async function exportBackup(){if(busy)return toast('正在保存，请稍候');rememberDraft();await pendingDraftWrites;busy=true;toast('正在生成完整备份…');try{const data=await new Promise((resolve,reject)=>{const tx=db.transaction(STORES,'readonly'),out={};for(const s of STORES){const r=tx.objectStore(s).getAll();r.onsuccess=()=>out[s]=r.result;}tx.oncomplete=()=>resolve(out);tx.onerror=()=>reject(tx.error);});const media=[];const refs=allMediaRefs(data);for(const item of data.media.filter(m=>refs.has(m.id)))media.push({id:item.id,data:await blobData(item.blob)});const backup={app:'ziyan',version:3,exportedAt:new Date().toISOString(),...data,media};const saved=await download(new Blob([JSON.stringify(backup)],{type:'application/json'}),`自言完整备份-${new Date().toISOString().slice(0,10)}.json`);toast(saved?(window.ZiyanFiles?'完整备份已保存':'完整备份已生成'):'已取消导出');}finally{busy=false;}}
function validateLegacyBackup(data){
 const invalid=()=>{throw new Error('备份格式不完整或已损坏，当前数据未改变');};
 const validId=v=>typeof v==='string'&&/^[\w-]{1,150}$/.test(v);
 const validTime=v=>Number.isFinite(v)&&Math.abs(v)<8e15;
 if(data?.app!=='ziyan'||![1,2].includes(data.version))invalid();
 for(const s of ['projects','messages','media'])if(!Array.isArray(data[s]))invalid();
 const out={};for(const s of STORES)out[s]=data.version===1&&!['projects','messages','media'].includes(s)?[]:data[s];
 for(const s of STORES)if(!Array.isArray(out[s]))invalid();
 const pids=new Set();out.projects=out.projects.map(p=>{if(!validId(p?.id)||pids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>40||typeof p.emoji!=='string'||p.emoji.length>16||!validTime(p.created)||!validTime(p.updated))invalid();pids.add(p.id);return {id:p.id,name:p.name,emoji:p.emoji,color:0,pinned:!!p.pinned,tasksOpen:!!p.tasksOpen,created:p.created,updated:p.updated};});
 const used=new Set();const validRecord=m=>{if(!validId(m?.id)||used.has(m.id)||!pids.has(m.projectId)||!validTime(m.created))invalid();used.add(m.id);};
 const legacy=[];out.messages=out.messages.map(m=>{validRecord(m);if(!['text','task','image','video','handwriting'].includes(m.type))invalid();const c={id:m.id,projectId:m.projectId,type:m.type,created:m.created};if(validTime(m.edited))c.edited=m.edited;if(['text','task'].includes(m.type)){if(typeof m.text!=='string'||!m.text.trim()||m.text.length>2000000)invalid();c.text=m.text;if(m.type==='task'){legacy.push({...c,done:!!m.done});return null;}}else{if(typeof m.name!=='string'||m.name.length>1000)invalid();c.name=m.name;if(m.type==='handwriting'){if(!Number.isInteger(m.pageCount)||m.pageCount<1||m.pageCount>200)invalid();c.pageCount=m.pageCount;}}return c;}).filter(Boolean);
 out.tasks=out.tasks.map(t=>{validRecord(t);if(typeof t.text!=='string'||!t.text.trim()||t.text.length>2000000)invalid();return {id:t.id,projectId:t.projectId,text:t.text,done:!!t.done,created:t.created};}).concat(legacy.map(({type,...t})=>t));
 if(legacy.length)out.projects.forEach(p=>{if(legacy.some(t=>t.projectId===p.id))p.tasksOpen=true;});
 const messageMap=new Map(out.messages.map(m=>[m.id,m])),mediaIds=new Set();out.media=out.media.map(item=>{const m=messageMap.get(item?.id);if(!m||!['image','video','handwriting'].includes(m.type)||mediaIds.has(item.id)||typeof item.data!=='string')invalid();const match=/^data:((?:image|video)\/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/]*={0,2})$/.exec(item.data);if(!match||!match[1].startsWith(m.type==='video'?'video/':'image/'))invalid();let binary;try{binary=atob(match[2]);}catch{invalid();}if(binary.length>200*1024*1024)invalid();mediaIds.add(item.id);return {id:item.id,blob:new Blob([Uint8Array.from(binary,c=>c.charCodeAt(0))],{type:match[1]})};});
 if(out.messages.some(m=>['image','video','handwriting'].includes(m.type)&&!mediaIds.has(m.id)))invalid();
 const ids=new Set();out.ink=out.ink.map(d=>{if(!validId(d?.id)||ids.has(d.id)||!pids.has(d.projectId)||typeof d.title!=='string'||d.title.length>100||!Array.isArray(d.pages)||!d.pages.length||d.pages.length>200)invalid();ids.add(d.id);if(d.draft){if(d.sourceId&&(messageMap.get(d.sourceId)?.type!=='handwriting'||messageMap.get(d.sourceId)?.projectId!==d.projectId))invalid();}else if(messageMap.get(d.id)?.type!=='handwriting'||messageMap.get(d.id).projectId!==d.projectId)invalid();const pages=d.pages.map(pg=>{if(!['blank','grid','lines'].includes(pg?.paper)||!Array.isArray(pg.strokes)||pg.strokes.length>50000)invalid();return {paper:pg.paper,strokes:pg.strokes.map(s=>{if(!validId(s?.id)||!['#ededed','#3cb474'].includes(s.color)||!Number.isFinite(s.width)||s.width<.5||s.width>30||!Array.isArray(s.points)||!s.points.length||s.points.length>200000)invalid();return {id:s.id,color:s.color,width:s.width,points:s.points.map(pt=>{if(!Array.isArray(pt)||pt.length!==3||!pt.every(Number.isFinite)||Math.abs(pt[0])>100000||Math.abs(pt[1])>100000||pt[2]<0||pt[2]>1)invalid();return pt;})};})};});return {id:d.id,projectId:d.projectId,title:d.title,pages,draft:!!d.draft,sourceId:d.sourceId||null,pageIndex:Math.min(Math.max(0,Math.floor(d.pageIndex)||0),pages.length-1),updated:validTime(d.updated)?d.updated:Date.now()};});
 if(out.messages.some(m=>m.type==='handwriting'&&(!out.ink.some(d=>d.id===m.id&&!d.draft)||out.ink.find(d=>d.id===m.id).pages.length!==m.pageCount)))invalid();
 const draftIds=new Set();out.drafts=out.drafts.map(d=>{if(!pids.has(d?.id)||draftIds.has(d.id)||typeof d.text!=='string'||typeof d.taskText!=='string'||d.text.length>2000000||d.taskText.length>2000000)invalid();draftIds.add(d.id);return {id:d.id,text:d.text,taskText:d.taskText,taskMode:!!d.taskMode};});
 const tids=new Set();out.templates=out.templates.map(t=>{if(!validId(t?.id)||tids.has(t.id)||typeof t.name!=='string'||!t.name.trim()||t.name.length>40||typeof t.text!=='string'||!t.text.trim()||t.text.length>2000000)invalid();tids.add(t.id);return {id:t.id,name:t.name,text:t.text};});
 if(data.version===1)out.templates=structuredClone(DEFAULT_TEMPLATES);
 return out;
}
async function readBackup(file){if(!file)return;if(busy)return toast('正在保存，请稍后再恢复');if(file.size>512*1024*1024)throw new Error('初版备份导入上限 512MB');let data;try{data=validateBackup(JSON.parse(await file.text()));}catch(e){throw new Error(e instanceof SyntaxError?'无法识别备份，当前数据未改变':e.message);}confirmAction('恢复完整备份？',`${data.projects.length} 个项目、${data.messages.length} 条笔记、${data.tasks.length} 项待办、${data.media.length} 个附件。将替换当前数据。`,'替换并恢复',async()=>{if(busy)throw new Error('正在保存，请稍后重试');rememberDraft();await pendingDraftWrites;busy=true;try{await transaction(STORES,tx=>{for(const s of STORES){const store=tx.objectStore(s);store.clear();data[s].forEach(item=>store.put(item));}});[...mediaUrls.keys()].forEach(revokeMedia);drafts.clear();data.drafts.forEach(d=>drafts.set(d.id,d));$('#message-input')?.remove();activeId=undefined;await refresh();taskMode=!!draft().taskMode;page='projects';inChat=false;search='';render();toast('备份已恢复');}finally{busy=false;}});}
async function storageInfo(){const el=$('#storage-info');if(!el)return;if(!navigator.storage?.estimate){el.textContent='浏览器不支持读取存储占用';return;}const [s,p]=await Promise.all([navigator.storage.estimate(),navigator.storage.persisted?.()]);if(el.isConnected)el.textContent=`约占用 ${((s.usage||0)/1048576).toFixed(1)} MB · ${p?'已获持久存储权限':'请定期导出备份'}`;}
function installHelp(){showDialog('<h3>安卓使用</h3><p class="dialog-copy">通过本机 localhost 或 HTTPS 打开，首次加载完成后，在 Chrome 菜单选择「添加到主屏幕」或「安装应用」。单文件 HTML 不需要安装，内容仍保存在当前浏览器；换浏览器请使用完整备份迁移。</p><div class="dialog-actions"><button class="primary" data-close>知道了</button></div>');}
