function dueEnd(date){if(!date)return null;const [y,m,d]=date.split('-').map(Number);return new Date(y,m-1,d,23,59,59,999).getTime();}
function validDue(date){if(date==null||date==='')return true;if(typeof date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(date))return false;const [y,m,d]=date.split('-').map(Number),dt=new Date(y,m-1,d);return dt.getFullYear()===y&&dt.getMonth()===m-1&&dt.getDate()===d;}
function daysLeft(t){if(!t.dueDate)return Infinity;const [y,m,d]=t.dueDate.split('-').map(Number),now=new Date();return Math.round((Date.UTC(y,m-1,d)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);}
function isUrgent(t){return !t.done&&!!t.dueDate&&daysLeft(t)<=3;}
function taskCompare(a,b){return Number(a.done)-Number(b.done)||((dueEnd(a.dueDate)??Infinity)-(dueEnd(b.dueDate)??Infinity))||b.created-a.created;}
function validReminder(value){return value==null||value===''||(typeof value==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(value));}
function syncReminders(){window.ZiyanAndroid?.syncTaskReminders?.(JSON.stringify(tasks.filter(t=>t.reminderEnabled&&!t.done&&t.reminderDate&&t.reminderTime).map(t=>({id:t.id,date:t.reminderDate,time:t.reminderTime,text:t.text.slice(0,200)}))));}
window.ziyanReminderRefresh=()=>{syncReminders();const panel=$('#reminder-settings');if(panel)panel.outerHTML=reminderSettings();};
function enableReminder(){if(!window.ZiyanAndroid?.enableTaskReminders)return toast('应用内预约需要安卓 APK');window.ZiyanAndroid.enableTaskReminders();toast('请完成系统授权；授权后返回，通知需保持开启');}
function openSystemAlarm(time,text){if(!time||!validReminder(time))return toast('请先选择提醒时间');if(!window.ZiyanAndroid?.setTaskAlarm)return toast('请在安卓 APK 中打开系统闹钟');const [hour,minute]=time.split(':').map(Number);window.ziyanPersistNow();window.ZiyanAndroid.setTaskAlarm(hour,minute,text.slice(0,200));}
window.ziyanAlarmResult=(ok)=>toast(ok?'请在系统闹钟中确认提醒':'无法打开系统闹钟，请检查设备是否安装时钟应用');
function taskReminder(tid){const t=tasks.find(t=>t.id===tid);if(!t)return;showDialog(`<h3>提醒闹钟</h3><label for="reminder-date">提醒日期</label><input id="reminder-date" type="date" value="${esc(t.reminderDate||'')}" aria-label="提醒日期"><label for="reminder-time">提醒时间（可选）</label><input id="reminder-time" type="time" value="${esc(t.reminderTime||'09:00')}" aria-label="提醒时间"><p class="dialog-copy">应用内提醒以系统通知发声，需要通知和精确闹钟授权；受静音、勿扰及通知渠道设置影响。完成、删除或清除会取消应用内预约。仅保存偏好不会预约。系统时钟入口独立管理，不能传入指定年月日。</p><div class="dialog-actions"><button class="secondary" data-close>取消</button><button class="secondary" id="reminder-clear">清除时间</button><button class="secondary" id="reminder-enable">启用应用内日期提醒</button><button class="secondary" id="reminder-save">保存偏好</button><button class="primary" id="reminder-open">保存并打开闹钟</button></div>`);
 let saving=false;const save=async (time,open=false,enabled=false)=>{if(saving)return;saving=true;dialog.querySelectorAll('button').forEach(b=>b.disabled=true);try{await taskWrites;const latest=tasks.find(t=>t.id===tid);if(!latest)throw new Error('待办已不存在');const updated={...latest,reminderTime:time,reminderDate:time?$('#reminder-date').value||null:null,reminderEnabled:enabled};await request('tasks','put',updated);tasks=tasks.map(t=>t.id===tid?updated:t);syncReminders();closeDialog();render();if(time&&open)openSystemAlarm(time,updated.text);else if(time)toast(enabled?'提醒已启用；请确保通知与精确闹钟授权开启':'已保存提醒偏好，尚未预约响铃');else toast('提醒时间已清除；已有闹钟请在系统时钟中关闭');}catch(error){saving=false;failure(error);dialog.querySelectorAll('button').forEach(b=>b.disabled=false);}};
 $('#reminder-open').onclick=()=>{const time=$('#reminder-time').value;if(!time||!validReminder(time))return toast('请选择提醒时间');save(time,true);};$('#reminder-enable').onclick=()=>{const date=$('#reminder-date').value,time=$('#reminder-time').value;if(!date||!time||new Date(date+'T'+time).getTime()<=Date.now())return toast('请选择未来日期和时间');if(!window.ZiyanAndroid?.reminderPermission?.()){toast('请在设置 → 提醒授权与状态中开启权限');return;}save(time,false,true);};$('#reminder-clear').onclick=()=>save(null);$('#reminder-save').onclick=()=>{const time=$('#reminder-time').value;if(!time)return toast('请选择提醒时间');save(time);};
}
function taskMetadata(t){const days=daysLeft(t),due=t.dueDate?(days<0?`逾期 ${-days} 天 · ${t.dueDate}`:days===0?'今天截止':days===1?'明天截止':`${t.dueDate} 截止`):'未设置截止日期';return `<small class="task-created">创建 ${dayTime(t.created)} ${clockTime(t.created)}</small><small class="task-due">${esc(due)}</small>${t.reminderTime||t.reminderDate?`<small class="task-reminder">提醒偏好 ${esc([t.reminderDate,t.reminderTime].filter(Boolean).join(' '))} · ${t.reminderEnabled?(window.ZiyanAndroid?.reminderPermission?.()?'应用内提醒已启用':'等待系统授权'):'未预约'}</small>`:''}`;}
