let taskWrites=Promise.resolve();
function editTaskInline(tid){const t=tasks.find(t=>t.id===tid),button=$(`[data-inline-task="${tid}"]`);if(!t||!button)return;const wrap=document.createElement('div');wrap.className='inline-task-edit';wrap.innerHTML=`<textarea aria-label="编辑待办文字" maxlength="2000000">${esc(t.text)}</textarea><button class="text-link">保存</button>`;button.replaceWith(wrap);const input=$('textarea',wrap);let done=false;const commit=()=>{if(done)return;const text=input.value.trim();if(!text&&!t.images?.length){toast('待办内容不能为空');input.focus();return;}done=true;taskWrites=taskWrites.catch(()=>{}).then(async()=>{const original=tasks.find(t=>t.id===tid);if(!original)return;const updated={...original,text};await request('tasks','put',updated);tasks=tasks.map(t=>t.id===tid?updated:t);document.querySelectorAll(`[data-task-row="${tid}"] .task-text`).forEach(el=>el.textContent=text||'图片待办');const b=document.createElement('button');b.className='task-text';b.dataset.inlineTask=tid;b.setAttribute('aria-label','编辑待办文字');b.textContent=text||'图片待办';wrap.replaceWith(b);if(page==='projects')render();});taskWrites.catch(e=>{done=false;failure(e);});};$('button',wrap).onpointerdown=e=>e.preventDefault();$('button',wrap).onclick=commit;input.onblur=commit;input.onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();commit();}if(e.key==='Escape'){done=true;wrap.replaceWith(button);}};input.focus();input.setSelectionRange(input.value.length,input.value.length);}
