function allMediaRefs(data){const refs=new Set();for(const m of data.messages||[]){if(['image','video','handwriting'].includes(m.type))refs.add(m.id);if(m.type==='richtext')richMedia(m.html).forEach(i=>refs.add(i));(m.attachments||[]).forEach(a=>refs.add(a.id));}for(const t of data.tasks||[])(t.images||[]).forEach(i=>refs.add(i));for(const d of data.drafts||[]){(d.images||[]).forEach(i=>refs.add(i));if(d.kind==='note')richMedia(d.html).forEach(i=>refs.add(i));}return refs;}
async function collectUnusedMedia(){const [ms,ts,ds,files]=await Promise.all(['messages','tasks','drafts','media'].map(s=>request(s,'getAll')));const refs=allMediaRefs({messages:ms,tasks:ts,drafts:ds});const unused=files.filter(m=>!refs.has(m.id));if(unused.length)await transaction(['media'],tx=>unused.forEach(m=>tx.objectStore('media').delete(m.id)));unused.forEach(m=>revokeMedia(m.id));}
