 const out=validateLegacyBackup({...data,version:2,messages:rawMessages,tasks:data.tasks.map(t=>({...t,text:t.text||'[图片待办]'})),drafts:baseDrafts,media:data.media.filter(m=>baseMediaIds.has(m?.id))});
 out.messages=out.messages.map(m=>extras.has(m.id)?{...m,type:'richtext',html:extras.get(m.id),text:richText(extras.get(m.id))}:m);
 out.messages=out.messages.map(m=>{const raw=rawMessageMap.get(m.id),origin=raw.origin,attachments=raw.attachments;
  if(origin!=null){if(!['combine','individual','raw'].includes(origin.format)||!(origin.sender===null||(typeof origin.sender==='string'&&origin.sender.length<=2000000))||!(origin.time===null||(typeof origin.time==='string'&&origin.time.length<=100))||!validId(origin.batch)||!Number.isInteger(origin.order)||origin.order<0||origin.order>=20000||!Number.isFinite(origin.importedAt))invalid();m.origin={sender:origin.sender,time:origin.time,format:origin.format,batch:origin.batch,order:origin.order,importedAt:origin.importedAt};}
  if(attachments!=null){if(!Array.isArray(attachments)||attachments.length>256||new Set(attachments.map(a=>a.id)).size!==attachments.length)invalid();m.attachments=attachments.map(a=>{if(!validId(a?.id)||typeof a.name!=='string'||a.name.length>1000||typeof a.type!=='string'||!/^video\/[a-zA-Z0-9.+-]+$/.test(a.type))invalid();return {id:a.id,name:a.name,type:a.type};});}return m;});
 const pids=new Set(out.projects.map(p=>p.id)),recordMap=new Map([...out.messages,...out.tasks].map(m=>[m.id,m]));
 const imageList=(value,max=100)=>{if(value==null)return [];if(!Array.isArray(value)||value.length>max||value.some(i=>!validId(i))||new Set(value).size!==value.length)invalid();return value;};
 out.tasks=out.tasks.map(t=>{const raw=rawTaskMap.get(t.id)||rawMessageMap.get(t.id);if(raw?.reminderEnabled!=null&&typeof raw.reminderEnabled!=='boolean')invalid();if(!raw||(!validDue(raw.dueDate)||!validReminder(raw.reminderTime)||!validDue(raw.reminderDate)))invalid();if(typeof raw.text!=='string'||(!raw.text.trim()&&!raw.images?.length))invalid();return {...t,text:raw.text,dueDate:raw.dueDate||null,reminderTime:raw.reminderTime||null,reminderDate:raw.reminderDate||null,reminderEnabled:raw.reminderEnabled===true,images:imageList(raw.images)};});
 const draftIds=new Set(out.drafts.map(d=>d.id));out.drafts=out.drafts.map(d=>({...d,unified:!!data.drafts.find(x=>x.id===d.id)?.unified}));
