 document.body.append(root);root.showModal();if(!incoming.wechat)$('#share-text',root).value=incoming.text||'';root.addEventListener('click',e=>e.stopPropagation());root.addEventListener('keydown',e=>e.stopPropagation());root.addEventListener('cancel',e=>{e.preventDefault();state.cancel();});$('#share-cancel',root).onclick=state.cancel;
